DROP TABLE IF EXISTS sf_guard_forgot_password;
DROP TABLE IF EXISTS sf_guard_remember_key;
DROP TABLE IF EXISTS sf_guard_user_permission;
DROP TABLE IF EXISTS sf_guard_user_group;
DROP TABLE IF EXISTS sf_guard_group_permission;
DROP TABLE IF EXISTS sf_guard_permission;
DROP TABLE IF EXISTS sf_guard_group;
DROP TABLE IF EXISTS sf_guard_user;
DROP TABLE IF EXISTS advertising;
DROP TABLE IF EXISTS teams_in_seasons;
DROP TABLE IF EXISTS seasons;
DROP TABLE IF EXISTS teams;
DROP TABLE IF EXISTS servers;
CREATE TABLE IF NOT EXISTS matchs (id BIGINT AUTO_INCREMENT PRIMARY KEY, server_id BIGINT, enable TINYINT(1), status INT, created_at DATETIME, updated_at DATETIME);
CREATE TABLE servers (id BIGINT AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(50) NOT NULL, rcon VARCHAR(50) NOT NULL, hostname VARCHAR(100) NOT NULL, tv_ip VARCHAR(100), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE teams (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL, shorthandle VARCHAR(50) NOT NULL, flag VARCHAR(2) NOT NULL, link VARCHAR(100), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE seasons (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(50) NOT NULL, event VARCHAR(50) NOT NULL, start DATETIME NOT NULL, end DATETIME NOT NULL, link VARCHAR(100), logo VARCHAR(255), active TINYINT(1), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE teams_in_seasons (id BIGINT AUTO_INCREMENT PRIMARY KEY, season_id BIGINT, team_id BIGINT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (season_id) REFERENCES seasons(id) ON DELETE CASCADE, FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE);
CREATE TABLE advertising (id BIGINT AUTO_INCREMENT PRIMARY KEY, season_id BIGINT, message VARCHAR(1000), active TINYINT(1), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (season_id) REFERENCES seasons(id) ON DELETE CASCADE);
CREATE TABLE sf_guard_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(255), last_name VARCHAR(255), email_address VARCHAR(255) NOT NULL UNIQUE, username VARCHAR(128) NOT NULL UNIQUE, algorithm VARCHAR(128) NOT NULL DEFAULT 'sha1', salt VARCHAR(128), password VARCHAR(128), is_active TINYINT(1) DEFAULT 1, is_super_admin TINYINT(1) DEFAULT 0, last_login DATETIME, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX is_active_idx (is_active));
CREATE TABLE sf_guard_group (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) UNIQUE, description VARCHAR(1000), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE sf_guard_permission (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) UNIQUE, description VARCHAR(1000), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL);
CREATE TABLE sf_guard_group_permission (group_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (group_id, permission_id), FOREIGN KEY (group_id) REFERENCES sf_guard_group(id) ON DELETE CASCADE, FOREIGN KEY (permission_id) REFERENCES sf_guard_permission(id) ON DELETE CASCADE);
CREATE TABLE sf_guard_user_permission (user_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (user_id, permission_id), FOREIGN KEY (user_id) REFERENCES sf_guard_user(id) ON DELETE CASCADE, FOREIGN KEY (permission_id) REFERENCES sf_guard_permission(id) ON DELETE CASCADE);
CREATE TABLE sf_guard_user_group (user_id BIGINT NOT NULL, group_id BIGINT NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (user_id, group_id), FOREIGN KEY (user_id) REFERENCES sf_guard_user(id) ON DELETE CASCADE, FOREIGN KEY (group_id) REFERENCES sf_guard_group(id) ON DELETE CASCADE);
CREATE TABLE sf_guard_remember_key (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT, remember_key VARCHAR(32), ip_address VARCHAR(50), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES sf_guard_user(id) ON DELETE CASCADE);
CREATE TABLE sf_guard_forgot_password (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, unique_key VARCHAR(255), expires_at DATETIME NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, FOREIGN KEY (user_id) REFERENCES sf_guard_user(id) ON DELETE CASCADE);
